## This module contains an algorithm to wordwrap a Unicode string.

import std/[strutils, unicode, assertions]


func olen(s: string; start, lastExclusive: int): int =
  var i = start
  result = 0
  while i < lastExclusive:
    inc result
    let L = graphemeLen(s, i)
    inc i, L

func wrapWords*(s: string, maxLineWidth = 80,
               splitLongWords = true,
               seps: set[char] = Whitespace,
               newLine = "\n"): string {.noSideEffect.} =
  ## Word wraps `s`.
  runnableExamples:
    assert "12345678901234567890".wrapWords() == "12345678901234567890"
    assert "123456789012345678901234567890".wrapWords(20) == "12345678901234567890\n1234567890"
    assert "Hello Bob. Hello John.".wrapWords(13, false) == "Hello Bob.\nHello John."
    assert "Hello Bob. Hello John.".wrapWords(13, true, {';'}) == "Hello Bob. He\nllo John."
  result = newStringOfCap(s.len + s.len shr 6)
  var spaceLeft = maxLineWidth
  var lastSep = ""

  var i = 0
  while true:
    var j = i
    let isSep = j < s.len and s[j] in seps
    while j < s.len and (s[j] in seps) == isSep: inc(j)
    if j <= i: break
    #yield (substr(s, i, j-1), isSep)
    if isSep:
      lastSep.setLen 0
      for k in i..<j:
        if s[k] notin {'\L', '\C'}: lastSep.add s[k]
      if lastSep.len == 0:
        lastSep.add ' '
        dec spaceLeft
      else:
        spaceLeft = spaceLeft - olen(lastSep, 0, lastSep.len)
    else:
      let wlen = olen(s, i, j)
      if wlen > spaceLeft:
        if splitLongWords and wlen > maxLineWidth:
          var k = 0
          while k < j - i:
            if spaceLeft <= 0:
              spaceLeft = maxLineWidth
              result.add newLine
            dec spaceLeft
            let L = graphemeLen(s, k+i)
            for m in 0 ..< L: result.add s[i+k+m]
            inc k, L
        else:
          spaceLeft = maxLineWidth - wlen
          result.add(newLine)
          for k in i..<j: result.add(s[k])
      else:
        spaceLeft = spaceLeft - wlen
        result.add(lastSep)
        for k in i..<j: result.add(s[k])
        #lastSep.setLen(0)
    i = j

/std/tables.nim:
import hashes, assertions

type
  Keyable* = concept ## Concept describing types usable as table keys (`==` plus `hash`).
    func `==`(a, b: Self): bool
    func hash(a: Self): Hash

  HashEntry = object
    fullhash: Hash
    position: int # index into `data`; 1 based so that 0 means "unfilled"
  Table*[K, V] = object ## Generic hash map storing key/value pairs (linear scan when tiny, open addressing otherwise).
    data: seq[(K, V)]
    hashes: seq[HashEntry]

func mustRehash(length, counter: int): bool {.inline.} =
  result = (length < counter div 2 + counter) or (length - counter < 4)

func isFilled(a: HashEntry): bool {.inline.} = a.position > 0

func resize(t: var seq[HashEntry]) =
  # does not have to be generic.
  let newLen = if t.len == 0: 4 else: t.len * 2
  var s = newSeq[HashEntry](newLen)
  for i in 0 ..< t.len:
    if isFilled(t[i]):
      var h = t[i].fullhash and high(s).uint
      while isFilled(s[h]): h = nextTry(h, high(s))
      s[h] = t[i]
  t = ensureMove s

const
  HashThreshold = 4

func fillHashPart[K: Keyable, V](t: var Table[K, V]) =
  t.hashes = newSeq[HashEntry](HashThreshold*2)
  for i in 0 ..< t.data.len:
    let fullhash = hash(t.data[i][0])
    var hi = fullhash and t.hashes.high.uint
    while isFilled(t.hashes[hi]): hi = nextTry(hi, high(t.hashes))
    t.hashes[hi] = HashEntry(fullhash: fullhash, position: i+1)

func rawGet[K: Keyable, V](t: Table[K, V]; k: K; kh: Hash): int =
  if t.data.len <= HashThreshold:
    for i in 0 ..< t.data.len:
      if t.data[i][0] == k: return i
  else:
    var h = kh and t.hashes.high.uint
    while isFilled(t.hashes[h]):
      let d = t.hashes[h]
      if d.fullhash == kh and t.data[d.position-1][0] == k:
        return d.position-1
      h = nextTry(h, high(t.hashes))
  result = -1

func contains*[K: Keyable, V](t: Table[K, V]; k: K): bool {.inline.} =
  ## True if `k` is stored in `t`.
  rawGet(t, k, hash(k)) >= 0

func hasKey*[K: Keyable, V](t: Table[K, V]; k: K): bool {.inline.} =
  ## Alias for `contains`.
  contains(t, k)

func getOrDefault*[K: Keyable, V: HasDefault](t: Table[K, V]; k: K): V =
  let idx = rawGet(t, k, hash(k))
  if idx >= 0:
    t.data[idx][1]
  else:
    default(V)

func getOrDefault*[K: Keyable, V](t: Table[K, V]; k: K; fallback: V): V =
  ## Return `t[k]` if the key is present, otherwise `fallback`.
  let idx = rawGet(t, k, hash(k))
  if idx >= 0:
    t.data[idx][1]
  else:
    fallback

func getOrQuit*[K: Keyable, V](t: Table[K, V]; k: K): var V =
  ## Like `[]`, but terminates the program if `k` is missing (after `assert`).
  let idx = rawGet(t, k, hash(k))
  {.cast(noSideEffect).}:
    assert idx >= 0
  t.data[idx][1]

when defined(nimony):
  func `[]`*[K: Keyable, V](t: Table[K, V]; k: K): var V {.raises.} =
    ## Retrieves `k`'s value or raises `KeyError` when absent.
    let idx = rawGet(t, k, hash(k))
    if idx < 0:
      raise KeyError
    t.data[idx][1]

else:
  func `[]`*[K, V](t: var Table[K, V]; k: K): var V {.raises.} =
    let idx = rawGet(t, k, hash(k))
    if idx < 0:
      raise KeyError
    t.data[idx][1]

  func `[]`*[K, V](t: Table[K, V]; k: K): V {.raises.} =
    let idx = rawGet(t, k, hash(k))
    if idx < 0:
      raise KeyError
    t.data[idx][1]

func rawPut[K: Keyable, V](t: var Table[K, V]; k: sink K; v: sink V; h: Hash) =
  if t.data.len == HashThreshold:
    fillHashPart t
  elif mustRehash(t.hashes.len, t.data.len):
    resize t.hashes
  t.data.add (k, v)
  var hi = h and t.hashes.high.uint
  while isFilled(t.hashes[hi]): hi = nextTry(hi, high(t.hashes))
  t.hashes[hi] = HashEntry(fullhash: h, position: t.data.len)

func `[]=`*[K: Keyable, V](t: var Table[K, V]; k: sink K; v: sink V) =
  ## Inserts or updates `k` with `v`.
  let h = hash(k)
  let idx = rawGet(t, k, h)
  if idx >= 0:
    t.data[idx][1] = v
  else:
    rawPut(t, k, v, h)

func mgetOrPut*[K: Keyable, V](t: var Table[K, V]; k: sink K; v: sink V): var V =
  ## Returns `t[k]`, inserting `v` when `k` was missing; result is mutable.
  let h = hash(k)
  var idx = rawGet(t, k, h)
  if idx < 0:
    rawPut(t, k, v, h)
    idx = t.data.len-1
  result = t.data[idx][1]

func len*[K, V](t: Table[K, V]): int {.inline.} =
  ## Number of key/value pairs stored in `t`.
  t.data.len

iterator pairs*[K, V](t: Table[K, V]): (lent K, lent V) =
  ## Yields every `(key, value)` stored in `t`.
  for i in 0 ..< t.data.len:
    yield (t.data[i][0], t.data[i][1])

iterator mpairs*[K, V](t: Table[K, V]): (lent K, var V) =
  ## Mutable variant of `pairs` (values can be updated in place).
  for i in 0 ..< t.data.len:
    yield (t.data[i][0], t.data[i][1])

iterator keys*[K, V](t: Table[K, V]): lent K =
  for i in 0 ..< t.data.len:
    yield t.data[i][0]

iterator values*[K, V](t: Table[K, V]): lent V =
  for i in 0 ..< t.data.len:
    yield t.data[i][1]

iterator mvalues*[K, V](t: var Table[K, V]): var V =
  for i in 0 ..< t.data.len:
    yield t.data[i][1]

func del*[K: Keyable, V](t: var Table[K, V]; k: K) =
  ## Remove `k` from `t`. No-op if absent. Preserves insertion order by
  ## shifting later entries down; the hash index is rebuilt afterwards
  ## because the shift renamed every entry's data position.
  let idx = rawGet(t, k, hash(k))
  if idx < 0: return
  var j = idx
  while j < t.data.len - 1:
    let next = t.data[j+1]
    t.data[j] = next
    inc j
  t.data.shrink(t.data.len - 1)
  if t.data.len > HashThreshold:
    # `rawGet` does NOT rebuild lazily: when `data.len > HashThreshold`
    # it indexes into `t.hashes` directly, so leaving `hashes = @[]`
    # turns the next lookup into an out-of-bounds read. Rebuild the
    # hash table sized to fit the current data.len. We can't just call
    # `fillHashPart` because it hardcodes size = `HashThreshold*2`,
    # which is too small once data has grown past 8 entries — the
    # probe loop would never terminate.
    var size = HashThreshold * 2
    while size < t.data.len * 2:
      size = size * 2
    t.hashes = newSeq[HashEntry](size)
    for i in 0 ..< t.data.len:
      let fullhash = hash(t.data[i][0])
      var hi = fullhash and t.hashes.high.uint
      while isFilled(t.hashes[hi]): hi = nextTry(hi, high(t.hashes))
      t.hashes[hi] = HashEntry(fullhash: fullhash, position: i+1)
  else:
    # data fits the linear-scan threshold; drop the hash table entirely.
    t.hashes.shrink(0)

func initTable*[K, V](): Table[K, V] =
  ## Creates an empty table.
  Table[K, V](data: @[], hashes: @[])

func clear*[K, V](t: var Table[K, V]) =
  ## Remove all entries from `t`.
  t.data.shrink(0)
  t.hashes = @[]

# Nimony's `Table` is already insertion-ordered (`data` is a `seq`), so
# `OrderedTable` is a simple alias for portability with code written
# against the Nim stdlib split.
type
  OrderedTable*[K, V] = Table[K, V]

func initOrderedTable*[K, V](): OrderedTable[K, V] {.inline.} = initTable[K, V]()

when isMainModule:
  import std/syncio

  var tab: Table[string, int] = initTable[string, int]()
  for i in 0..<1000:
    tab[$i] = i
    assert hasKey(tab, $i)
    assert not hasKey(tab, $(i+1))
    assert tab[$i] == i
  #echo tab.data
  #echo tab.hashes
  assert tab.hasKey("100")
  echo tab.getOrDefault("500")
  echo tab["600"]
  tab.mgetOrPut("abc", -12) = -24
  echo tab["abc"]

/std/widestrs.nim:
## Nim support for C/C++'s `wide strings`:idx:.

{.feature: "lenientnils".}

type
  Utf16Char* = distinct int16

when not (defined(cpu16) or defined(cpu8)):
  type
    WideCString* = ptr UncheckedArray[Utf16Char]

    WideCStringObj* = object
      bytes: int
      data: WideCString

  func `=destroy`(a: WideCStringObj) =
    if a.data != nil:
      #when compileOption("threads"):
      #  deallocShared(a.data)
      #else:
        dealloc(a.data)

  func `=wasMoved`(a: var WideCStringObj) =
    a.data = nil

  func `=copy`(a: var WideCStringObj; b: WideCStringObj) {.error.}

  func `=sink`(a: var WideCStringObj; b: WideCStringObj) =
    a.bytes = b.bytes
    a.data = b.data

  func createWide(a: var WideCStringObj; bytes: int) =
    a.bytes = bytes
    #when compileOption("threads"):
    #  a.data = cast[typeof(a.data)](allocShared0(bytes))
    #else:
    #  a.data = cast[typeof(a.data)](alloc0(bytes))
    a.data = cast[WideCString](alloc(bytes))

  template `[]`*(a: WideCStringObj; idx: int): Utf16Char = a.data[idx]
  template `[]=`*(a: WideCStringObj; idx: int; val: Utf16Char) = a.data[idx] = val

  template nullWide(): untyped = WideCStringObj(bytes: 0, data: nil)

  func toWideCString*(x: WideCStringObj): WideCString {.inline.} =
    result = x.data

  func rawData*(x: WideCStringObj): WideCString {.inline.} =
    result = x.data

  func ord(arg: Utf16Char): int = int(cast[uint16](arg))

  func len*(w: WideCString): int =
    ## returns the length of a widestring. This traverses the whole string to
    ## find the binary zero end marker!
    result = 0
    while int16(w[result]) != 0'i16: inc result

  const
    UNI_REPLACEMENT_CHAR = Utf16Char(0xFFFD'i16)
    UNI_MAX_BMP = 0x0000FFFF
    UNI_MAX_UTF16 = 0x0010FFFF
    # UNI_MAX_UTF32 = 0x7FFFFFFF
    # UNI_MAX_LEGAL_UTF32 = 0x0010FFFF

    halfShift = 10
    halfBase = 0x0010000
    halfMask = 0x3FF

    UNI_SUR_HIGH_START = 0xD800
    UNI_SUR_HIGH_END = 0xDBFF
    UNI_SUR_LOW_START = 0xDC00
    UNI_SUR_LOW_END = 0xDFFF
    UNI_REPL = 0xFFFD

  template ones(n: untyped): untyped = ((1 shl n)-1)

  template fastRuneAt(s: cstring, i, L: int, result: untyped, doInc = true) =
    ## Returns the unicode character `s[i]` in `result`. If `doInc == true`
    ## `i` is incremented by the number of bytes that have been processed.
    if int(s[i]) <= 127:
      result = int(s[i])
      if doInc: inc(i)
    elif int(s[i]) shr 5 == 0b110:
      #assert(ord(s[i+1]) shr 6 == 0b10)
      if i <= L - 2:
        result = (int(s[i]) and (ones(5))) shl 6 or (int(s[i+1]) and ones(6))
        if doInc: inc(i, 2)
      else:
        result = UNI_REPL
        if doInc: inc(i)
    elif int(s[i]) shr 4 == 0b1110:
      if i <= L - 3:
        #assert(ord(s[i+1]) shr 6 == 0b10)
        #assert(ord(s[i+2]) shr 6 == 0b10)
        result = (int(s[i]) and ones(4)) shl 12 or
                (int(s[i+1]) and ones(6)) shl 6 or
                (int(s[i+2]) and ones(6))
        if doInc: inc(i, 3)
      else:
        result = UNI_REPL
        if doInc: inc(i)
    elif int(s[i]) shr 3 == 0b11110:
      if i <= L - 4:
        #assert(ord(s[i+1]) shr 6 == 0b10)
        #assert(ord(s[i+2]) shr 6 == 0b10)
        #assert(ord(s[i+3]) shr 6 == 0b10)
        result = (int(s[i]) and ones(3)) shl 18 or
                (int(s[i+1]) and ones(6)) shl 12 or
                (int(s[i+2]) and ones(6)) shl 6 or
                (int(s[i+3]) and ones(6))
        if doInc: inc(i, 4)
      else:
        result = UNI_REPL
        if doInc: inc(i)
    else:
      result = 0xFFFD
      if doInc: inc(i)

  iterator runes(s: cstring, L: int): int =
    var
      i = 0
      result: int
    while i < L:
      fastRuneAt(s, i, L, result, true)
      yield result

  func newWideCString*(size: int): WideCStringObj =
    result = default(WideCStringObj)
    createWide(result, size * 2 + 2)

  func newWideCString*(source: cstring, L: int): WideCStringObj =
    ## Warning:: `source` needs to be preallocated with the length `L`
    result = default(WideCStringObj)
    createWide(result, L * 2 + 2)
    var d = 0
    for ch in runes(source, L):

      if ch <= UNI_MAX_BMP:
        if ch >= UNI_SUR_HIGH_START and ch <= UNI_SUR_LOW_END:
          result[d] = UNI_REPLACEMENT_CHAR
        else:
          result[d] = cast[Utf16Char](uint16(ch))
      elif ch > UNI_MAX_UTF16:
        result[d] = UNI_REPLACEMENT_CHAR
      else:
        let ch = ch - halfBase
        result[d] = cast[Utf16Char](uint16((ch shr halfShift) + UNI_SUR_HIGH_START))
        inc d
        result[d] = cast[Utf16Char](uint16((ch and halfMask) + UNI_SUR_LOW_START))
      inc d
    result[d] = Utf16Char(0)

  func newWideCString*(s: cstring): WideCStringObj =
    if s.isNil: return nullWide()

    result = newWideCString(s, s.len)

  func newWideCString*(s: var string): WideCStringObj =
    # seems to be a bit buggy ...
    result = newWideCString(s.toCString, s.len)

  func `$`*(w: WideCString, estimate: int, replacement: int = 0xFFFD): string =
    result = newStringOfCap(estimate + estimate shr 2)

    var i = 0
    while w[i].int16 != 0'i16:
      var ch = ord(w[i])
      inc i
      if ch >= UNI_SUR_HIGH_START and ch <= UNI_SUR_HIGH_END:
        # If the 16 bits following the high surrogate are in the source buffer...
        let ch2 = ord(w[i])

        # If it's a low surrogate, convert to UTF32:
        if ch2 >= UNI_SUR_LOW_START and ch2 <= UNI_SUR_LOW_END:
          ch = (((ch and halfMask) shl halfShift) + (ch2 and halfMask)) + halfBase
          inc i
        else:
          #invalid UTF-16
          ch = replacement
      elif ch >= UNI_SUR_LOW_START and ch <= UNI_SUR_LOW_END:
        #invalid UTF-16
        ch = replacement

      if ch < 0x80:
        result.add chr(ch)
      elif ch < 0x800:
        result.add chr((ch shr 6) or 0xc0)
        result.add chr((ch and 0x3f) or 0x80)
      elif ch < 0x10000:
        result.add chr((ch shr 12) or 0xe0)
        result.add chr(((ch shr 6) and 0x3f) or 0x80)
        result.add chr((ch and 0x3f) or 0x80)
      elif ch <= 0x10FFFF:
        result.add chr((ch shr 18) or 0xf0)
        result.add chr(((ch shr 12) and 0x3f) or 0x80)
        result.add chr(((ch shr 6) and 0x3f) or 0x80)
        result.add chr((ch and 0x3f) or 0x80)
      else:
        # replacement char(in case user give very large number):
        result.add chr(0xFFFD shr 12 or 0b1110_0000)
        result.add chr(0xFFFD shr 6 and ones(6) or 0b10_0000_00)
        result.add chr(0xFFFD and ones(6) or 0b10_0000_00)

  func `$`*(s: WideCString): string =
    result = s $ 80

  func `$`*(s: WideCStringObj, estimate: int, replacement: int = 0xFFFD): string =
    `$`(s.data, estimate, replacement)

  func `$`*(s: WideCStringObj): string =
    $(s.data)

  func len*(w: WideCStringObj): int {.inline.} =
    len(w.data)

