  ## Appends `elem` to the end of `s`, growing storage if necessary.
  let L = s.len
  if s.capInBytes < (L * sizeof(T)) + sizeof(T):
    if not resize(s, 1):
      # It is our responsibility to destroy the `sink` element if
      # it could not be added:
      `=destroy`(elem)
      return
